    if(node == null) {
        throw new IllegalArgumentException("Node must not be null");
    }
    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;
    node.height = Math.max(node.left == null ? 0 : node.left.height, node.right == null ? 0 : node.right.height) + 1;
    newParent.height = Math.max(newParent.left == null ? 0 : newParent.left.height, node.right == null ? 0 : newParent.right.height) + 1;
    return newParent;
}

