public Mappings diffStructure(String tableName, Mappings mappings) {
    if ( tableName == null || mappings == null || mappings.getBody() == null || mappings.getBody().isEmpty()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    // Extract indexes associated with the table in the mappings
    Mappings existingIndexes = mappings.getBody().get("existingIndexes");
    if (existingIndexes == null || existingIndexes.getBody() == null || existingIndexes.getBody().isEmpty()) {
        throw new IllegalArgumentException("Index mappings are missing or empty");
    }
    List<Integer> existingTableIndexes = new LinkedList<>();
    for (Index index : existingIndexes.getBody()) {
        if (index.containsKey("tableName")) {
            existingTableIndexes.add(Integer.parseInt(index.get("tableName")));
        }
    }

    // Extract indexes associated with the table in the provided mappings
    Mappings providedIndexes = mappings.getBody().get("providedIndexes");
    if (providedIndexes == null || providedIndexes.getBody() == null || providedIndexes.getBody().isEmpty()) {
        throw new IllegalArgumentException("Index mappings are missing or empty");
    }
    List<Integer> providedTableIndexes = new LinkedList<>();
    for (Index index : providedIndexes.getBody()) {
        if (index.containsKey("tableName")) {
            providedTableIndexes.add(Integer.parseInt(index.get("tableName")));
        }
    }

    // Find fields that exist in the newer mappings but not in the older mappings of the same table
    List<String> newerFields = new LinkedList<>();
    for (Index index : providedIndexes.getBody()) {
        if (!existingTableIndexes.contains(index.get("tableName"))) {
            newerFields.add(index.get("fieldName"));
        }
    }

    // Return mappings with newer fields
    Mappings_diffStructure newMappings = new Mappings_diffStructure();
    newMappings.setBody(newerFields);

    return newMappings;
}

