    if (this.data == null || this.data.length < this.length) {
        byte[] newData = new byte[this.data == null ? 1 : this.data.length + size];
        System.arraycopy(this.data, 0, newData, 0, this.data == null ? 0 : this.data.length);
        this.data = newData;
    } else {
