public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Initialize variables to store the total size, remaining bytes, and max chunk size
    int totalSize = 0;
    int remainingBytes = 0;
    int maxChunkSize = MAX_CHUNK;

    // Validate and handle edge cases
    if (out == null) {
        throw new IllegalArgumentException("Output cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Initialize a temporary buffer to hold the current chunk
    Object[] tempBuffer = node.getData();

    // Iterate through each chunk in the linked list
    while (node.getNext() != null) {
        // If the current chunk is smaller or equal to the maximum chunk size
        if (tempBuffer.length <= maxChunkSize) {
            // Copy the current chunk to the output
            out.write(tempBuffer, 0, tempBuffer.length);
            // Increase the total size by the chunk size
            totalSize += tempBuffer.length;
            // Decrease the remaining bytes by the chunk size
            remainingBytes -= tempBuffer.length;
        } else {
            // If the current chunk is larger than the maximum chunk size
            // Write the remaining part of the chunk to the output
            int BytesToWrite = Math.min(maxChunkSize, tempBuffer.length);
            out.write(tempBuffer, 0, BytesToWrite);
            // Increase the total size by the written part of the chunk
            totalSize += BytesToWrite;
            // Decrease the remaining bytes by the written part of the chunk
            remainingBytes -= BytesToWrite;
            // Swap the current chunk with the next chunk
            Object[] nextChunk = node.getNext().getData();
            node.setData(nextChunk);
            maxChunkSize = MAX_CHUNK; // Reset the maximum chunk size
            tempBuffer = nextChunk; // Update the temporary buffer
        }
    }

    // If there is any remaining part of the last chunk
    if (tempBuffer.length > 0) {
        int BytesToWrite = Math.min(maxChunkSize, tempBuffer.length);
        out.write(tempBuffer, 0, BytesToWrite);
        totalSize += BytesToWrite;
        remainingBytes -= BytesToWrite;
    }

    return totalSize;
}

