public String format(LoggingEvent event) {
    // Check if the logging event is not null
    if (event == null) {
        throw new IllegalArgumentException("The logging event cannot be null.");
    }

    StringBuilder formattedEvent = new StringBuilder();

    // Format the timestamp
    formattedEvent.append(event.getTimestampDisplay()).append(" ");

    // Format the thread name
    formattedEvent.append(event.getThreadName()).append(" ");

    // Format the logger name
    formattedEvent.append(event.getLoggerName()).append(" ");

    // Format the level
    formattedEvent.append(event.getLevel().toString()).append(" ");

    // Format the class name
    formattedEvent.append(event.getFQN()).append(" ");

    // Format the location info
    formattedEvent.append(event.getLocationInfo()).append(" ");

    // Format the message
    formattedEvent.append(event.getFormattedMessage()).append(" ");

    // Format the detail and throwable information (if available)
    try {
        StackTraceElement[] stackTrace = event.getThrowableInformation().getStackTrace();
        if (stackTrace != null && stackTrace.length > 0) {
            formattedEvent.append("\nCaused by: ");
            for (StackTraceElement element : stackTrace) {
                formattedEvent.append("at ").append(element.getClassName()).append ".".append(element.getMethodName()).append("(").append(element.getFileName()).append(":").append(element.getLineNumber()).append(")\n");
            }
        }
    } catch (NullPointerException ignored) {
        // Ignore if no stack trace information is available
    }

    return formattedEvent.toString();
}

