public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    Pattern escapedQuote = Pattern.compile("\\\\'|\\\\n");
    Matcher matcher = escapedQuote.matcher(str);
    StringBuilder unescapedStr = new StringBuilder();
    while (matcher.find()) {
        char ch = matcher.group().charAt(1);
        if (ch == '\'' && matcher.start() > 0 && str.charAt(matcher.start() - 1) == '\\') {
            unescapedStr.append(ch);
        } else {
            unescapedStr.append("\\");
            unescapedStr.append(ch);
        }
    }
    return unescapedStr.toString();
}

