final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length() / 2) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }

    int start = classFileBuffer.length() - 2 * constantPoolEntryIndex;
    while (start > 0 && charBuffer[start] != Utf8Constants.UTF8_MARK) {
        start--;
    }

    if (start == 0 || charBuffer[start] != Utf8Constants.UTF8_MARK) {
        throw new IllegalArgumentException("Invalid UTF-8 entry");
    }

    int length = 0;
    while (start < classFileBuffer.length() - 2 * constantPoolEntryIndex - 1 && classFileBuffer[start] != Utf8Constants.UTF8_MARK) {
        start++;
        length++;
    }

    if (classFileBuffer[start] != Utf8Constants.UTF8_MARK) {
        throw new IllegalArgumentException("Invalid UTF-8 entry");
    }

    char[] utf8String = new char[length];
    System.arraycopy(charBuffer, start + 1, utf8String, 0, length);
    return new String(utf8String);
}

