private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Ensure the bounds list is not null
    if(bounds == null){
        throw new IllegalArgumentException("Bound list cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Reverse the list to get the suffix sum easily
    for(int i = bounds.size() - 1; i >= 0; i--){
        // Add the current number to the total sum and then add the suffix sum to the list
        totalSum += bounds.get(i);
        suffixSum.add(totalSum);
    }

    // Reverse back to get the proper suffix sum order
    Collections.reverse(suffixSum);

    return Pair.of(suffixSum, totalSum);
}

